import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Find features with strong association (p < 0.05, |t| > 2)
    strong_features = []
    for i, fid in enumerate(feats.ids):
        # Use t-statistic threshold based on feature type encoding
        # The types appear to be numeric codes indicating feature types
        try:
            if abs(feats.types[i]) > 2:  # Using absolute value for threshold
                strong_features.append(fid)
        except (TypeError, ValueError):
            # Skip if types[i] is not numeric
            continue

    # Remove near-duplicates (correlated pairs with |r| >= 0.6)
    correlated_pairs = set()
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids[i+1:], i+1):
            if abs(np.corrcoef(feats.x[:,i], feats.x[:,j])[0,1]) >= 0.6:
                correlated_pairs.add((min(fid1,fid2), max(fid1,fid2)))

    # Build set of unique features (remove duplicates)
    unique_features = set()
    for fid in strong_features:
        # Check if this feature is part of any correlated pair
        is_duplicate = False
        for p1, p2 in correlated_pairs:
            if fid == p1 or fid == p2:
                is_duplicate = True
                break
        if not is_duplicate:
            unique_features.add(fid)

    # If no strong features, return empty design
    if not unique_features:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Try to find product terms among top features
    top_features = list(unique_features)[:10]  # Limit search space

    # Look for pairs with significant interaction
    best_product = None
    best_p = 1.0
    for i, f1 in enumerate(top_features):
        for j, f2 in enumerate(top_features[i+1:], i+1):
            # Create product feature
            col1 = feats.column(f1)
            col2 = feats.column(f2)
            product_vals = feats.x[:,col1] * feats.x[:,col2]

            # Test significance of product using logistic regression
            X = np.column_stack([feats.x[:,col1], feats.x[:,col2], product_vals])
            model = LogisticRegression(fit_intercept=True, solver='liblinear')
            model.fit(X, feats.y)
            # Approximate p-value via permutation test
            base_score = model.score(X, feats.y)
            perm_scores = []
            for _ in range(100):
                perm_y = feats.y[np.random.permutation(len(feats.y))]
                perm_model = LogisticRegression(fit_intercept=True, solver='liblinear')
                perm_model.fit(X, perm_y)
                perm_scores.append(perm_model.score(X, perm_y))
            p_val = np.mean(np.array(perm_scores) >= base_score)

            if p_val < best_p:
                best_p = p_val
                best_product = (f1, f2)

    # If we found a good product term
    if best_product and best_p < 0.05:
        f1, f2 = best_product
        return Design(
            drivers=(f1,),
            columns=(f1, f2),
            products=(best_product,),
            loadings={f1: 1.0}
        )

    # Otherwise, use simple approach
    if len(unique_features) > 0:
        # Return top feature as driver if available
        return Design(
            drivers=(list(unique_features)[0],),
            columns=(list(unique_features)[0],),
            products=(),
            loadings={list(unique_features)[0]: 1.0}
        )

    return Design(drivers=(), columns=(), products=(), loadings={})

